	{
		Add(entries, 1, "Bulbasaur", "Seed", "Bulbasaur can be seen napping in bright sunlight. There is a seed on its back. By soaking up the sun's rays, the seed grows progressively larger.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, PokemonType.Poison, 0.7f, 6.9f);
		Add(entries, 2, "Ivysaur", "Seed", "To support its bulb, Ivysaur's legs grow sturdy. If it spends more time lying in the sunlight, the bud will soon bloom into a large flower.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, PokemonType.Poison, 1.0f, 13.0f);
		Add(entries, 3, "Venusaur", "Seed", "Venusaur's flower is said to take on vivid colors if it gets plenty of nutrition and sunlight. The flower's aroma soothes the emotions of people.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, PokemonType.Poison, 2.0f, 100.0f);
