		Add(entries, 5, "Charmeleon", "Flame", "Without pity, its sharp claws destroy foes. If it encounters a strong enemy, it becomes agitated, and the flame on its tail flares with a bluish white color.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Fire, null, 1.1f, 19.0f);
		Add(entries, 6, "Charizard", "Flame", "A Charizard flies about in search of strong opponents. It breathes intense flames that can melt any material. However, it will never torch a weaker foe.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Fire, PokemonType.Flying, 1.7f, 90.5f);
		Add(entries, 7, "Squirtle", "Tiny Turtle", "Its shell is not just for protection. Its rounded shape and the grooves on its surface minimize resistance in water, enabling Squirtle to swim at high speeds.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Starter", PokemonType.Water, null, 0.5f, 9.0f);
		Add(entries, 8, "Wartortle", "Turtle", "Its large tail is covered with rich, thick fur that deepens in color with age. The scratches on its shell are evidence of this Pokémon's toughness in battle.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Water, null, 1.0f, 22.5f);
		Add(entries, 9, "Blastoise", "Shellfish", "The waterspouts that protrude from its shell are highly accurate. Their bullets of water can precisely nail tin cans from a distance of over 160 feet.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Starter", PokemonType.Water, null, 1.6f, 85.5f);
		Add(entries, 10, "Caterpie", "Worm", "Its voracious appetite compels it to devour leaves bigger than itself without hesitation. It releases a terribly strong odor from its antennae.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Bug, null, 0.3f, 2.9f);
