		Add(entries, 14, "Kakuna", "Cocoon", "It remains virtually immobile while it clings to a tree. However, on the inside, it busily prepares for evolution. This is evident from how hot its shell becomes.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Primavera & Verão", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Bug, PokemonType.Poison, 0.6f, 10.0f);
		Add(entries, 15, "Beedrill", "Poison Bee", "A Beedrill is extremely territorial. For safety reasons, no one should ever approach its nest. If angered, they will attack in a swarm.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Bug, PokemonType.Poison, 1.0f, 29.5f);
