		Add(entries, 23, "Ekans", "Snake", "An Ekans curls itself up in a spiral while it rests. This position allows it to quickly respond to an enemy from any direction with a threat from its upraised head.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Poison, null, 2.0f, 6.9f);
