		Add(entries, 27, "Sandshrew", "Mouse", "When it curls up in a ball, it can make any attack bounce off harmlessly. Its hide has turned tough and solid as a result of living in the desert.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Ground, null, 0.6f, 12.0f);
