		Add(entries, 486, "Regigigas", "Colossal", "There is an enduring legend that states this Pokémon shaped Regirock, Regice, and Registeel out of clay, ice, and magma.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Legendary", PokemonType.Normal, null, 3.7f, 420.0f);
		Add(entries, 487, "Giratina", "Renegade", "This Pokémon is said to live in a world on the reverse side of ours, where common knowledge is distorted and strange. It was banished for its violence.", "Caverna da Caveira (Andar 100+) & Templo das Sombras", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Legendary", PokemonType.Ghost, PokemonType.Dragon, 4.5f, 750.0f);
		Add(entries, 488, "Cresselia", "Lunar", "Those who sleep holding one of Cresselia's feathers are assured of joyful dreams. It is said to represent the crescent moon.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera, Verão & Outono", "Qualquer Clima (Sol ou Chuva)", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Psychic, null, 1.5f, 85.6f);
		Add(entries, 489, "Phione", "Sea Drifter", "When the water warms, they inflate the flotation sac on their heads and drift languidly on the sea in packs. It always returns to where it was born.", "Ilha Gengibre (Recife Oeste) & Profundezas Oceânicas", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Mythical", PokemonType.Water, null, 0.4f, 3.1f);
		Add(entries, 490, "Manaphy", "Seafaring", "Water makes up 80% of its body. It starts its life with a wondrous power that permits it to bond with any kind of Pokémon.", "Ilha Gengibre (Recife Oeste) & Profundezas Oceânicas", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Amanhecer Dourado (06:00h às 10:00h)", "Mythical", PokemonType.Water, null, 0.3f, 1.4f);
		Add(entries, 491, "Darkrai", "Pitch-Black", "It chases people and Pokémon from its territory by causing them to experience deep, nightmarish slumbers. However, it means no harm.", "Caverna da Caveira (Andar 100+) & Templo das Sombras", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Mythical", PokemonType.Dark, null, 1.5f, 50.5f);
		Add(entries, 492, "Shaymin", "Gratitude", "The flowers all over its body bloom if it is lovingly hugged and senses gratitude. It dissolves toxins in the air to transform ruined land into a lush field of flowers.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Mythical", PokemonType.Grass, null, 0.2f, 2.1f);
		Add(entries, 493, "Arceus", "Espécie", "Arceus habita os ecossistemas naturais da região e possui habilidades únicas.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Amanhecer Dourado (06:00h às 10:00h)", "Mythical", PokemonType.Normal, null, 1.0f, 20.0f);
		Add(entries, 494, "Victini", "Victory", "This Pokémon brings victory. It is said that Trainers with Victini always win, regardless of the type of encounter.", "Vulcão da Ilha Gengibre (Caldeira) & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Meia-Noite (22:00h às 02:00h)", "Mythical", PokemonType.Psychic, PokemonType.Fire, 0.4f, 4.0f);
		Add(entries, 495, "Snivy", "Grass Snake", "It is very intelligent and calm. Being exposed to lots of sunlight makes its movements swifter. When they are not feeling well, their tails droop.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, null, 0.6f, 8.1f);
		Add(entries, 496, "Servine", "Grass Snake", "When it gets dirty, its leaves can't be used in photosynthesis, so it always keeps clean. They avoid attacks by sinking into the shadows of thick foliage.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, null, 0.8f, 16.0f);
		Add(entries, 497, "Serperior", "Regal", "They raise their heads to intimidate foes, but only give it their all when fighting powerful opponents who are not fazed by the glare from its noble eyes.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, null, 3.3f, 63.0f);
		Add(entries, 498, "Tepig", "Fire Pig", "It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp. It blows fire through its nose.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Starter", PokemonType.Fire, null, 0.5f, 9.9f);
		Add(entries, 499, "Pignite", "Fire Pig", "The more it eats, the more fuel it has to make the fire in its stomach stronger. When it is angered, the intensity of the flame increases.", "Deserto de Calico & Encostas do Vulcão da Ilha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Manhã & Tarde (06:00h às 19:00h)", "Starter", PokemonType.Fire, PokemonType.Fighting, 1.0f, 55.5f);
		Add(entries, 500, "Emboar", "Fire Pig", "It is adept at using many different moves. It can throw a fire punch by setting its fists on fire with its fiery chin. It cares deeply about its friends.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Fire, PokemonType.Fighting, 1.6f, 150.0f);
		Add(entries, 501, "Oshawott", "Sea Otter", "The scalchop on its stomach isn't just used for battle, it can be used to break open hard berries as well. It is made from the same element as its claws.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Starter", PokemonType.Water, null, 0.5f, 5.9f);
		Add(entries, 502, "Dewott", "Discipline", "Strict training and disclipine leads it to master its flowing double-scalchop technique. Scalchop techniques differ from one Dewott to another.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Primavera & Verão", "Chuva, Tempestade ou Dias Úmidos", "Manhã & Tarde (06:00h às 19:00h)", "Starter", PokemonType.Water, null, 0.8f, 24.5f);
		Add(entries, 503, "Samurott", "Formidable", "One swing of the seamitars attached to its armor can fell an opponent. A simple glare from one of them is enough to intimidate most enemies.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Water, null, 1.5f, 94.6f);
		Add(entries, 504, "Patrat", "Scout", "Extremely cautious, they take shifts to maintain a constant watch of their nest. Using food stored in cheek pouches, they can keep watch for days.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Primavera, Verão & Outono", "Qualquer Clima (Sol ou Chuva)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, null, 0.5f, 11.6f);
		Add(entries, 505, "Watchog", "Lookout", "Using luminescent matter, it makes its eyes and body glow and stuns attacking opponents. Keen eyesight lets them see in the dark.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Normal, null, 1.1f, 27.0f);
		Add(entries, 506, "Lillipup", "Puppy", "It faces strong opponents with great courage. Because it doesn't yelp, it's extremely popular with Trainers who live in apartment buildings.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Normal, null, 0.4f, 4.1f);
		Add(entries, 507, "Herdier", "Loyal Dog", "Its dense black fur grows continuously. The high cost of keeping its hard fur properly groomed makes this a troublesome Pokémon to train.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, null, 0.9f, 14.7f);
		Add(entries, 508, "Stoutland", "Big-Hearted", "Intelligent, good-natured, and valiant, there could be no concern that it would ever attack people. Some parents even trust it to babysit.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Normal, null, 1.2f, 61.0f);
		Add(entries, 509, "Purrloin", "Devious", "Their deceptively cute act is the perfect ruse. They steal from people for fun, but their victims can't help but forgive them.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Todas as Estações (Ano Inteiro)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, null, 0.4f, 10.1f);
		Add(entries, 510, "Liepard", "Cruel", "Many Trainers are drawn to their beautiful form and fur. These Pokémon vanish and appear unexpectedly. They run silently in the night.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Primavera & Verão", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, null, 1.1f, 37.5f);
		Add(entries, 511, "Pansage", "Grass Monkey", "This Pokémon dwells deep in the forest. It's good at finding berries and gathers them from all over. It's kind enough to share them with friends.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 0.6f, 10.5f);
		Add(entries, 512, "Simisage", "Thorn Monkey", "Ill tempered, it attacks enemies by swinging its barbed tail around wildly. The leaf growing on its head is very bitter.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 1.1f, 30.5f);
		Add(entries, 513, "Pansear", "High Temp", "The fire within the tuft on its head can reach up to 600ºF. Very intelligent, it roasts berries before eating them. It likes to help people.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Fire, null, 0.6f, 11.0f);
		Add(entries, 514, "Simisear", "Ember", "It loves sweets because they become energy for the fire burning inside its body. It scatters embers from its head and tail to sear its opponents.", "Deserto de Calico & Encostas do Vulcão da Ilha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fire, null, 1.0f, 28.0f);
		Add(entries, 515, "Panpour", "Spray", "The water stored inside the tuft of its head is rich in nutrients. It waters plants using its tail, plants that receive its water grow large.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Water, null, 0.6f, 13.5f);
		Add(entries, 516, "Simipour", "Geyser", "It can shoot highly-pressurised water from its tail with enough power to break through a solid concrete wall. It prefers places with clean water.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Water, null, 1.0f, 29.0f);
		Add(entries, 517, "Munna", "Dream Eater", "This Pokémon appears before people and Pokémon who are having nightmares and eats those dreams. Munna always float in the air.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Psychic, null, 0.6f, 23.3f);
		Add(entries, 518, "Musharna", "Drowsing", "The mist emanating from their foreheads is packed with the dreams of people and Pokémon. It changes into different colors depending on the dream that was eaten.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Psychic, null, 1.1f, 60.5f);
		Add(entries, 519, "Pidove", "Tiny Pigeon", "This very forgetful Pokémon will wait for a new order from its Trainer even though it already has one. Flocks often gather in parks and plazas.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Flying, 0.3f, 2.1f);
		Add(entries, 520, "Tranquill", "Wild Pigeon", "No matter where in the world it goes, it knows where its nest is, so it can always return to its Trainer's location regardless of the distance.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Flying, 0.6f, 15.0f);
		Add(entries, 521, "Unfezant", "Proud", "Males have plumage on their heads. The females' flying abilities surpass those of the males. They will only let themselves feel close to their Trainers.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Flying, 1.2f, 29.0f);
		Add(entries, 522, "Blitzle", "Electrified", "Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate with one another.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Electric, null, 0.8f, 29.8f);
		Add(entries, 523, "Zebstrika", "Thunderbolt", "When Zebstrika run at full speed, the sound of thunder reverberates. It is dangerous when it's angry as it shoots lightning from its mane in all directions.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Electric, null, 1.6f, 79.5f);
		Add(entries, 524, "Roggenrola", "Mantle", "The hexagonal cavity is its ear. It walks in the direction of sounds it hears, but if the sounds cease, it panics and topples over.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Rock, null, 0.4f, 18.0f);
		Add(entries, 525, "Boldore", "Ore", "Its orange crystal is a mass of energy. Just one crystal fragment would provide enough fuel for a hundred dump trucks. When it is healthy, its core sticks out.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Rock, null, 0.9f, 102.0f);
		Add(entries, 526, "Gigalith", "Compressed", "The blasts of energy it makes from sunbeams have terrifying power. However, it's not able to fire its blasts at night or on rainy days.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Rock, null, 1.7f, 260.0f);
		Add(entries, 527, "Woobat", "Bat", "Its habitat is dark forests and caves. Suction from its nostrils enables it to stick to cave walls during sleep. It leaves a heart-shaped mark behind.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Psychic, PokemonType.Flying, 0.4f, 2.1f);
		Add(entries, 528, "Swoobat", "Courting", "Anyone who comes into contact with the ultrasonic waves emitted by a courting male experiences a positive mood shift.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Psychic, PokemonType.Flying, 0.9f, 10.5f);
		Add(entries, 529, "Drilbur", "Mole", "It can dig through the ground at a speed of 30 mph by spinning its body. It could give a car running aboveground a good race.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Ground, null, 0.3f, 8.5f);
		Add(entries, 530, "Excadrill", "Subterrene", "More than 300 feet below the surface, they build mazelike nests. Their activity can be destructive to subway tunnels, but it can also help with construction.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Ground, PokemonType.Steel, 0.7f, 40.4f);
		Add(entries, 531, "Audino", "Hearing", "Its auditory sense is astounding. Using the feelers on its ears, it can tell how someone is feeling or when an egg might hatch.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, null, 1.1f, 31.0f);
		Add(entries, 532, "Timburr", "Muscular", "These Pokémon appear at building sites and help out with construction. They always carry squared logs. As they grow, they carry bigger logs.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fighting, null, 0.6f, 12.5f);
		Add(entries, 533, "Gurdurr", "Muscular", "They strengthen their bodies by carrying steel beams. This Pokémon is so muscular and strongly built that even a group of wrestlers could not make it budge an inch.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Fighting, null, 1.2f, 40.0f);
		Add(entries, 534, "Conkeldurr", "Muscular", "They use concrete pillars as walking canes. Rather than rely solely on force, they master moves that utilize the centrifugal force of spinning concrete.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Primavera & Verão", "Qualquer Clima (Prefere Sol)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Fighting, null, 1.4f, 87.0f);
		Add(entries, 535, "Tympole", "Tadpole", "By vibrating its cheeks, it emits sound waves imperceptible to humans. It uses the rhythm of these sounds to talk and warns others of danger.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Water, null, 0.5f, 4.5f);
		Add(entries, 536, "Palpitoad", "Vibration", "It lives in the water and on land. When they vibrate the bumps on their heads, they can make waves in water or earthquake-like vibrations on land.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Water, PokemonType.Ground, 0.8f, 17.0f);
		Add(entries, 537, "Seismitoad", "Vibration", "It increases the power of its punches by vibrating the bumps on its fists. They can also shoot paralyzing liquid from their head bumps.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Water, PokemonType.Ground, 1.5f, 62.0f);
		Add(entries, 538, "Throh", "Judo", "When it tightens its belt, it becomes stronger. Wild Throh use vines to weave their own belts. It changes belts as it gets more powerful.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fighting, null, 1.3f, 55.5f);
		Add(entries, 539, "Sawk", "Karate", "The sound of Sawk punching boulders and trees can be heard all the way from the mountains where they train. Disturbing their training angers them.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Fighting, null, 1.4f, 51.0f);
		Add(entries, 540, "Sewaddle", "Sewing", "It chews up leaves and sews them with sticky thread extruded from its mouth. Since this Pokémon makes its own clothes, it is a mascot for fashion designers.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Bug, PokemonType.Grass, 0.3f, 2.5f);
		Add(entries, 541, "Swadloon", "Leaf-Wrapped", "Forests where Swadloon live have superb foliage because the nutrients they make from fallen leaves nourish the plant life.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Bug, PokemonType.Grass, 0.5f, 7.3f);
		Add(entries, 542, "Leavanny", "Nurturing", "It keeps its eggs warm with heat from fermenting leaves. It also uses leaves to weave warm wrappings for Sewaddle by using the silk secreted from its mouth.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Bug, PokemonType.Grass, 1.2f, 20.5f);
		Add(entries, 543, "Venipede", "Centipede", "Using the feelers on its head and tail, it picks up vibrations in the air to determine its prey's location and state. It is brutally aggressive.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Bug, PokemonType.Poison, 0.4f, 5.3f);
		Add(entries, 544, "Whirlipede", "Curlipede", "Storing energy for evolution, it sits. But when attacked, it spins its body at high speed like a wheel and then crashes furiously into its opponent.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Bug, PokemonType.Poison, 1.2f, 58.5f);
		Add(entries, 545, "Scolipede", "Megapede", "With quick movements, it chases down its foes, attacking relentlessly with its horns until it prevails. Then it finishes them off with deadly poison.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Bug, PokemonType.Poison, 2.5f, 200.5f);
		Add(entries, 546, "Cottonee", "Cotton Puff", "When it finds others of its kind, they all stick together. When enough of them have collected, the mass resembles a cumulonimbus cloud.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Primavera & Verão", "Qualquer Clima (Prefere Sol)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, null, 0.3f, 0.6f);
		Add(entries, 547, "Whimsicott", "Windveiled", "It rides on the wind and slips into people's homes. After it has turned a room into a cotton-filled mess, it giggles to itself and takes off.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Normal, null, 0.7f, 6.6f);
		Add(entries, 548, "Petilil", "Bulb", "By pruning the leaves on its head with regularity, this Pokémon can be grown into a fine plump shape. These bitter leaves refresh those who eat them.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 0.5f, 6.6f);
		Add(entries, 549, "Lilligant", "Flowering", "Even veteran Trainers face a challenge in getting its beautiful flower to bloom. It withers away if a trainer does not take good care of it.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 1.1f, 16.3f);
		Add(entries, 550, "Basculin", "Hostile", "It used to be a common food source. The meat of red Basculin is on the fatty side and it's more popular with the youth. Its temperament is vicious and aggressive.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Primavera & Verão", "Chuva, Tempestade ou Dias Úmidos", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Water, null, 1.0f, 18.0f);
		Add(entries, 551, "Sandile", "Desert Croc", "It conceals itself in the sand and chomps down on the legs of any prey that unwarily walk over it. Its favorite food is Trapinch.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ground, PokemonType.Dark, 0.7f, 15.2f);
		Add(entries, 552, "Krokorok", "Desert Croc", "They move in groups of a few individuals. Thanks to the special membrane covering its eyes, it can see its surroundings clearly, even in the dead of night.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ground, PokemonType.Dark, 1.0f, 33.4f);
		Add(entries, 553, "Krookodile", "Intimidate", "Very violent Pokémon, they never allow their prey to escape. Their jaws are so powerful, they can crush the body of an automobile.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ground, PokemonType.Dark, 1.5f, 96.3f);
		Add(entries, 554, "Darumaka", "Zen Charm", "When its internal fire is burning, it cannot calm down and it runs around. When the fire diminishes, it pulls its limbs into its body and falls asleep.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Fire, null, 0.6f, 37.5f);
		Add(entries, 555, "Darmanitan", "Blazing", "When one is injured in a fierce battle, it transforms into a stone statue. Then it meditates and sharpens its mind and fights on mentally.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Fire, null, 1.3f, 92.9f);
		Add(entries, 556, "Maractus", "Cactus", "Arid regions are their habitat. When it moves rhythmically, it makes a sound similar to maracas, making the surprised Pokémon flee.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 1.0f, 28.0f);
		Add(entries, 557, "Dwebble", "Rock Inn", "It makes a hole in a stone of a suitable size. If that rock breaks, the Pokémon remains agitated until it locates a replacement.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Bug, PokemonType.Rock, 0.3f, 14.5f);
		Add(entries, 558, "Crustle", "Stone Home", "Competing for territory, Crustle fight viciously. The one whose boulder is broken is the loser of the battle and begins to weaken.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Bug, PokemonType.Rock, 1.4f, 200.0f);
		Add(entries, 559, "Scraggy", "Shedding", "Its skin has a rubbery elasticity, so it can reduce damage by defensively pulling its skin up to its neck. Its skull is massively thick.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Fighting, 0.6f, 11.8f);
		Add(entries, 560, "Scrafty", "Hoodlum", "Groups of them beat up anything that enters their territory. The one with the biggest crest is the group leader, and is the most respected.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Primavera, Verão & Outono", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Fighting, 1.1f, 30.0f);
		Add(entries, 561, "Sigilyph", "Avianoid", "The guardians of an ancient city, they always fly the same route while keeping watch for invaders. They use their psychic power to attack enemies.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Psychic, PokemonType.Flying, 1.4f, 14.0f);
		Add(entries, 562, "Yamask", "Spirit", "These Pokémon arose from the spirits of people interred in graves in past ages. Each of them carries a mask that used to be its face when it was human.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, null, 0.5f, 1.5f);
		Add(entries, 563, "Cofagrigus", "Coffin", "Grave robbers who mistake them for real coffins and get too close end up trapped inside their bodies. Their bodies are covered in pure gold.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Outono & Inverno", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, null, 1.7f, 76.5f);
		Add(entries, 564, "Tirtouga", "Prototurtle", "Reputed to be the ancestor of most turtle Pokémon, it lived in warm seas about a hundred million years ago. It was restored from a fossil.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Water, PokemonType.Rock, 0.7f, 16.5f);
		Add(entries, 565, "Carracosta", "Prototurtle", "They can live both in the ocean and on land. Incredible jaw strength enables them to chew up steel beams and rocks along with their prey.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Water, PokemonType.Rock, 1.2f, 81.0f);
		Add(entries, 566, "Archen", "First Bird", "Said to be the ancestor of all bird Pokémon, Archen itself could not actually fly but moved by hopping from treetop to treetop.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Rock, PokemonType.Flying, 0.5f, 9.5f);
		Add(entries, 567, "Archeops", "First Bird", "They are intelligent and will cooperate to catch prey. When one Archeops had the prey cornered, another would swoop on it.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Rock, PokemonType.Flying, 1.4f, 32.0f);
		Add(entries, 568, "Trubbish", "Trash Bag", "It gorges on trash until its stomach is full. Then it belches toxic gas. An unlucky whiff of this gas will put a person in the hospital.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Poison, null, 0.6f, 31.0f);
		Add(entries, 569, "Garbodor", "Trash Heap", "Beware the poisonous liquid it shoots from its right arm. If even a little of it gets on you, you'll experience the full effects of this unidentified toxin.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Poison, null, 1.9f, 107.3f);
		Add(entries, 570, "Zorua", "Tricky Fox", "To protect themselves from danger, they hide their true identities by transforming into people and Pokémon. Apparently, it often transforms into a silent child.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Primavera & Verão", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, null, 0.7f, 12.5f);
		Add(entries, 571, "Zoroark", "Illusion Fox", "Bonds between these Pokémon are very strong. It protects the safety of its pack by tricking its opponents. They defend their lair with illusory scenery.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, null, 1.6f, 81.1f);
		Add(entries, 572, "Minccino", "Chinchilla", "These Pokémon prefer a tidy habitat. They greet one another by rubbing each other with their tails, which are always kept well groomed and clean.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Normal, null, 0.4f, 5.8f);
		Add(entries, 573, "Cinccino", "Scarf", "Their white fur feels amazing to touch. Cinccino's body is coated in a special oil that repels dust and helps it deflect attacks, such as punches.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, null, 0.5f, 7.5f);
		Add(entries, 574, "Gothita", "Fixation", "They intently observe both Trainers and Pokémon. Apparently, Gothita are looking at something that only they can see. Their ribbonlike feelers increase their power.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Psychic, null, 0.4f, 5.8f);
		Add(entries, 575, "Gothorita", "Manipulate", "Starlight is the source of their power. They use hypnosis to control people and Pokémon. Tales of Gothorita leading them astray are told in every corner.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Psychic, null, 0.7f, 18.0f);
		Add(entries, 576, "Gothitelle", "Astral Body", "Starry skies thousands of light-years away are visible in the space distorted by their intense psychic power. When it learns its Trainer's life span, it cries in sadness.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Psychic, null, 1.5f, 44.0f);
		Add(entries, 577, "Solosis", "Cell", "Because their bodies are enveloped in a special liquid, they are fine in any environment, no matter how severe. They can use telepathy to talk with others.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Psychic, null, 0.3f, 1.0f);
		Add(entries, 578, "Duosion", "Mitosis", "When their brains, now divided in two, are thinking the same thoughts, these Pokémon exhibit their maximized psychic power.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Psychic, null, 0.6f, 8.0f);
		Add(entries, 579, "Reuniclus", "Multiplying", "They use psychic power to control their arms, which are made of a special liquid. When Reuniclus shake hands, a network forms between their brains.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Psychic, null, 1.0f, 20.1f);
		Add(entries, 580, "Ducklett", "Water Bird", "These bird Pokémon are excellent divers. They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Primavera, Verão & Outono", "Chuva, Tempestade ou Dias Úmidos", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Water, PokemonType.Flying, 0.5f, 5.5f);
		Add(entries, 581, "Swanna", "White Bird", "Despite their elegant appearance, they can flap their wings strongly and fly for thousands of miles. The one in the middle is the leader of the flock.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Water, PokemonType.Flying, 1.3f, 24.2f);
		Add(entries, 582, "Vanillite", "Fresh Snow", "The temperature of their breath is -58ºF. They create snow crystals and make snow fall in the areas around them. Vanillite is treasured by households in warm regions.", "Minas Congeladas (Andares 40-79) & Montanha no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Qualquer Clima (Prefere Sol)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Ice, null, 0.4f, 5.7f);
		Add(entries, 583, "Vanillish", "Icy Snow", "Vanillish has existed since the Ice Age. It controls particles of ice, freezes its opponents, and then shatters them with a headbutt.", "Pico da Montanha, Ferrovia & Floresta no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Ice, null, 1.1f, 41.0f);
		Add(entries, 584, "Vanilluxe", "Snowstorm", "Each of its two heads has a brain, and when they are in agreement, it attacks its enemies by exhaling a violent blizzard. It makes snow clouds inside its body.", "Minas Congeladas (Andares 40-79) & Montanha no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Qualquer Clima (Sol ou Chuva)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Ice, null, 1.3f, 57.5f);
		Add(entries, 585, "Deerling", "Season", "Deerling have different scents depending on the season. In early spring, these Pokémon give off a delicate, sweet, and calming scent.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Grass, 0.6f, 19.5f);
		Add(entries, 586, "Sawsbuck", "Season", "Some people call Sawsbuck the harbingers of spring because the plants growing on its horns change according to the season. The leader possesses magnificent horns.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Grass, 1.9f, 92.5f);
		Add(entries, 587, "Emolga", "Sky Squirrel", "It glides using its cape-like membrane. It grills berries and bug Pokémon with electric shocks from the pouches on its cheeks and makes a meal of them.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Electric, PokemonType.Flying, 0.4f, 5.0f);
		Add(entries, 588, "Karrablast", "Clamping", "When they feel threatened, they spit an acidic liquid to drive attackers away. For some reason they evolve while they are in the same place as Shelmet.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono", "Qualquer Clima (Sol ou Chuva)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Bug, null, 0.5f, 5.9f);
		Add(entries, 589, "Escavalier", "Cavalry", "Wearing the shell covering they stole from Shelmet, they defend themselves and attack with two lances. The steel armor protects their whole body.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Bug, PokemonType.Steel, 1.0f, 33.0f);
		Add(entries, 590, "Foongus", "Mushroom", "It lures Pokémon in with its pattern that looks just like a Poké Ball, then releases its poison spores. Why it resembles a Poké Ball is unknown.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, PokemonType.Poison, 0.2f, 1.0f);
		Add(entries, 591, "Amoonguss", "Mushroom", "It lures prey close by dancing and waving its arm caps, which resemble Poké Balls, in a swaying motion, but very few Pokémon are fooled by this.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, PokemonType.Poison, 0.6f, 10.5f);
		Add(entries, 592, "Frillish", "Floating", "If its veil-like arms stun and wrap an opponent, that foe will be dragged five miles below the surface to its lair, never to return.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Primavera, Verão & Outono", "Chuva, Tempestade ou Dias Úmidos", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Water, PokemonType.Ghost, 1.2f, 33.0f);
		Add(entries, 593, "Jellicent", "Floating", "They propel themselves by expelling absorbed seawater from their bodies. It's said there's a castle of ships Jellicent have sunk on the seafloor.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Water, PokemonType.Ghost, 2.2f, 135.0f);
		Add(entries, 594, "Alomomola", "Caring", "When they find a wounded Pokémon, they embrace it and bring it to shore. The special membrane enveloping Alomomola has the ability to heal wounds.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Water, null, 1.2f, 31.6f);
		Add(entries, 595, "Joltik", "Attaching", "Since they can't generate their own electricity, they attach themselves to large-bodied Pokémon and absorb static electricity, which they store in a pouch.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Bug, PokemonType.Electric, 0.1f, 0.6f);
		Add(entries, 596, "Galvantula", "EleSpider", "It creates barriers from electrified silk that stun foes. This works as a weapon as well as a defense. While it is immobilized by shock, they leisurely consume it.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono", "Tempestade de Raios ou Chuva", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Bug, PokemonType.Electric, 0.8f, 14.3f);
		Add(entries, 597, "Ferroseed", "Thorn Seed", "It absorbs the iron it finds in the rock while clinging to the ceiling of caves. When threatened, it attacks by shooting a barrage of spikes.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, PokemonType.Steel, 0.6f, 18.8f);
		Add(entries, 598, "Ferrothorn", "Thorn Pod", "It fights by swinging around its three spiky feelers and shooting spikes. A hit from these steel spikes can reduce a boulder to rubble.", "Minas da Montanha (1-39), Pedreira & Deserto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, PokemonType.Steel, 1.0f, 110.0f);
		Add(entries, 599, "Klink", "Gear", "Two bodies comprise a fixed pair. The two minigears that mesh together are predetermined. Each will rebound from other minigears without meshing.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Steel, null, 0.3f, 21.0f);
		Add(entries, 600, "Klang", "Gear", "A minigear and big gear comprise its body. Spinning minigears are rotated at high speed and repeatedly fired away. It is dangerous if the gears don't return.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Steel, null, 0.6f, 51.0f);
		Add(entries, 601, "Klinklang", "Gear", "Its red core functions as an energy tank. It is rotated at high speed for a rapid energy charge. It fires the charged energy through its spikes into an area.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Steel, null, 0.6f, 81.0f);
		Add(entries, 602, "Tynamo", "EleFish", "These Pokémon move in schools. One alone can emit only a trickle of electricity, so a group of them gathers to unleash a powerful electric shock.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Electric, null, 0.2f, 0.3f);
		Add(entries, 603, "Eelektrik", "EleFish", "These Pokémon have a big appetite. It wraps itself around its prey and paralyzes it with electricity from the round spots on its sides. Then it chomps.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Electric, null, 1.2f, 22.0f);
		Add(entries, 604, "Eelektross", "EleFish", "They crawl out of the ocean using their arms. They will attack prey on shore and immediately drag it into the ocean, with their sucker mouths.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Electric, null, 2.1f, 80.5f);
		Add(entries, 605, "Elgyem", "Cerebral", "It psychically squeezes the brain of its foe, causing unendurable headaches. Rumors of its origin are linked to a UFO crash site in the desert 50 years ago.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Psychic, null, 0.5f, 9.0f);
		Add(entries, 606, "Beheeyem", "Cerebral", "It can manipulate an opponent's memory. Apparently, it communicates by flashing its three fingers, but those patterns haven't been decoded.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Psychic, null, 1.0f, 34.5f);
		Add(entries, 607, "Litwick", "Candle", "While Litwick shines a light and pretends to be a guide, it absorbs the life force of any who follow it, which becomes the fuel that it burns.", "Deserto de Calico & Encostas do Vulcão da Ilha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, PokemonType.Fire, 0.3f, 3.1f);
		Add(entries, 608, "Lampent", "Lamp", "This ominous Pokémon is feared. Through cities it wanders, searching for the spirits of the fallen. The spirits it absorbs fuel its baleful fire.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, PokemonType.Fire, 0.6f, 13.0f);
		Add(entries, 609, "Chandelure", "Luring", "Being consumed in Chandelure's flame burns up the spirit, leaving the body behind. By waving the flames on its arms, it puts its foes into a hypnotic trance.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, PokemonType.Fire, 1.0f, 34.3f);
		Add(entries, 610, "Axew", "Tusk", "They mark their territory by leaving gashes in trees with their tusks. If a tusk breaks, a new one grows in quickly, harder and sturdier than the last.", "Caverna da Caveira, Vulcão da Ilha & Cume da Montanha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Dragon, null, 0.6f, 18.0f);
		Add(entries, 611, "Fraxure", "Axe Jaw", "Their tusks can shatter rocks. A broken tusk will not grow back, so it diligently sharpens its tusks on river rocks after the end of a battle.", "Ilha Gengibre (Cratera do Vulcão) & Caverna dos Piratas", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Dragon, null, 1.0f, 36.0f);
		Add(entries, 612, "Haxorus", "Axe Jaw", "They are kind but can be relentless when defending territory. Their sturdy tusks will stay sharp even if used to cut steel beams.", "Caverna da Caveira, Vulcão da Ilha & Cume da Montanha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Dragon, null, 1.8f, 105.5f);
		Add(entries, 613, "Cubchoo", "Chill", "Its nose is always running. Their snot is a barometer of health. When healthy, their snot is sticky and the power of their ice moves increases.", "Pico da Montanha, Ferrovia & Floresta no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Ice, null, 0.5f, 8.5f);
		Add(entries, 614, "Beartic", "Freezing", "It freezes its breath to create fangs and claws of ice to fight with. Very able in the water, it swims around in northern seas and catches prey.", "Minas Congeladas (Andares 40-79) & Montanha no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Ice, null, 2.6f, 260.0f);
		Add(entries, 615, "Cryogonal", "Crystallize", "They are born in snow clouds. When its body temperature goes up, it turns into steam and vanishes. When its temperature lowers, it returns to ice.", "Pico da Montanha, Ferrovia & Floresta no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Ice, null, 1.1f, 148.0f);
		Add(entries, 616, "Shelmet", "Snail", "When attacked, it defends itself by closing the lid of its shell. It evolves when bathed in an electric-like energy along with Karrablast.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Bug, null, 0.4f, 7.7f);
		Add(entries, 617, "Accelgor", "Shell Out", "When its body dries out, it weakens. So, to prevent dehydration, it wraps itself in layers of thin membrane. It is very light and fights with ninja-like movements.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Bug, null, 0.8f, 25.3f);
		Add(entries, 618, "Stunfisk", "Trap", "It conceals itself in the mud of the seashore. Then it waits. When prey touch it, it delivers a jolt of electricity. It smiles when transmitting electricity.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Ground, PokemonType.Electric, 0.7f, 11.0f);
		Add(entries, 619, "Mienfoo", "Martial Arts", "They have mastered elegant combos. As they concentrate, their battle moves become swifter and more precise. What it lacks in power, it makes up for in quantity.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fighting, null, 0.9f, 20.0f);
		Add(entries, 620, "Mienshao", "Martial Arts", "They use the long fur on their arms as a whip to strike their opponents. Its arm attacks come with such rapidity that they cannot even be seen.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Fighting, null, 1.4f, 35.5f);
		Add(entries, 621, "Druddigon", "Cave", "It warms its body by absorbing sunlight with its wings. When its body temperature falls, it can no longer move. It uses its sharp claws to catch prey.", "Ilha Gengibre (Cratera do Vulcão) & Caverna dos Piratas", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Dragon, null, 1.6f, 139.0f);
		Add(entries, 622, "Golett", "Automaton", "These Pokémon are thought to have been created by the science of an ancient and mysterious civilization. It's been active for thousands of years.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ground, PokemonType.Ghost, 1.0f, 92.0f);
		Add(entries, 623, "Golurk", "Automaton", "Golurk were created to protect people and Pokémon by an ancient civilisation. Removing the seal on its chest makes its internal energy go out of control.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ground, PokemonType.Ghost, 2.8f, 330.0f);
		Add(entries, 624, "Pawniard", "Sharp Blade", "Ignoring their injuries, groups attack by sinking the blades that cover their bodies into their prey. If battling dulls them, it sharpens them on stones by the river.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Steel, 0.5f, 10.2f);
		Add(entries, 625, "Bisharp", "Sword Blade", "This pitiless Pokémon commands a group of Pawniard to hound prey into immobility. It battles to become the boss, but will be driven from the group if it loses.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Steel, 1.6f, 70.0f);
		Add(entries, 626, "Bouffalant", "Bash Buffalo", "Their fluffy fur absorbs damage, even if they strike foes with a fierce headbutt. Their headbutts have enough destructive force to derail a train.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Normal, null, 1.6f, 94.6f);
		Add(entries, 627, "Rufflet", "Eaglet", "With its sharp claws, this Pokémon pierces its prey, and then it pecks at them. Although it also consumes berries, it's a carnivore at heart.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Flying, 0.5f, 10.5f);
		Add(entries, 628, "Braviary", "Valiant", "For the sake of its friends, this brave warrior of the sky will not stop battling, even if it is injured. One can carry a car while flying.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Flying, 1.5f, 41.0f);
		Add(entries, 629, "Vullaby", "Diapered", "It can't fly yet and must wait until its wings have developed more. They guard their posteriors with bones that were gathered by Mandibuzz.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Todas as Estações (Ano Inteiro)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Flying, 0.5f, 9.0f);
		Add(entries, 630, "Mandibuzz", "Bone Vulture", "They adorn themselves beautifully with bones. This is supposedly an effort to attract males, but no male Mandibuzz have ever been found.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Primavera & Verão", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Flying, 1.2f, 39.5f);
		Add(entries, 631, "Heatmor", "Anteater", "It draws in air through its tail, transforms it into fire, and uses it like a tongue. They burn through Durant's steel bodies and consume their insides.", "Deserto de Calico & Encostas do Vulcão da Ilha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fire, null, 1.4f, 58.0f);
		Add(entries, 632, "Durant", "Iron Ant", "Durant dig nests in mountains. Individuals each play different roles in driving Heatmor, their natural predator, away from their colony.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Bug, PokemonType.Steel, 0.3f, 33.0f);
		Add(entries, 633, "Deino", "Irate", "Lacking sight, it's unaware of its surroundings, so it bumps into things and eats anything that moves. Approaching it carelessly is dangerous.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Todas as Estações (Ano Inteiro)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Dragon, 0.8f, 17.3f);
		Add(entries, 634, "Zweilous", "Hostile", "After it has eaten up all the food in its territory, it moves on to another area. Whichever head eats more than the other gets to be the leader.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Dragon, 1.4f, 50.0f);
		Add(entries, 635, "Hydreigon", "Brutal", "This brutal Pokémon travels the skies on its six wings. The heads on their arms do not have brains. They use all three heads to consume and destroy everything.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Outono & Inverno", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Dragon, 1.8f, 160.0f);
		Add(entries, 636, "Larvesta", "Torch", "This Pokémon was believed to have been born from the sun. It spews fire from its horns and encases itself in a cocoon of fire when it evolves.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Bug, PokemonType.Fire, 1.1f, 28.8f);
		Add(entries, 637, "Volcarona", "Sun", "When volcanic ash darkened the atmosphere, it appeared and saved Pokémon from freezing, Volcarona's fire provided a replacement for the sun.", "Deserto de Calico & Encostas do Vulcão da Ilha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Bug, PokemonType.Fire, 1.6f, 46.0f);
		Add(entries, 638, "Cobalion", "Iron Will", "It has a body and heart of steel. This legendary Pokémon battled against humans to protect Pokémon. Its personality is calm and composed.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Steel, PokemonType.Fighting, 2.1f, 250.0f);
		Add(entries, 639, "Terrakion", "Cavern", "Spoken of in legend, this Pokémon used its phenomenal power to destroy a castle in its effort to protect Pokémon that had lost their homes in a war among humans.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Legendary", PokemonType.Rock, PokemonType.Fighting, 1.9f, 260.0f);
		Add(entries, 640, "Virizion", "Grassland", "Its head sprouts horns as sharp as blades. Legends say this Pokémon used whirlwind-like movements to confound and swiftly cut its opponents.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Amanhecer Dourado (06:00h às 10:00h)", "Legendary", PokemonType.Grass, PokemonType.Fighting, 2.0f, 200.0f);
		Add(entries, 641, "Tornadus", "Cyclone", "Tornadus expels massive energy from its tail, causing severe storms. Its power can blow entire houses away. It zooms through the sky at 200 mph.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Flying, null, 1.5f, 63.0f);
		Add(entries, 642, "Thundurus", "Bolt Strike", "The spikes on its tail discharge immense bolts of lightning. Countless charred remains mar the landscape of places through which Thundurus has passed.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Legendary", PokemonType.Electric, PokemonType.Flying, 1.5f, 61.0f);
		Add(entries, 643, "Reshiram", "Vast White", "This Pokémon appears in legends. It sends flames into the air from its tail, burning up everything around it. It helps those who want to build a world of truth.", "Vulcão da Ilha Gengibre (Caldeira) & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Amanhecer Dourado (06:00h às 10:00h)", "Legendary", PokemonType.Dragon, PokemonType.Fire, 3.2f, 330.0f);
		Add(entries, 644, "Zekrom", "Deep Black", "This legendary Pokémon can scorch the world with lightning. It has a generator that creates electricity in its tail. It assists those with strong ideals.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Dragon, PokemonType.Electric, 2.9f, 345.0f);
		Add(entries, 645, "Landorus", "Abundance", "The energy that comes pouring from its tail increases the nutrition in the soil, granting bountiful crops. It has been hailed as “The Guardian of the Fields.”", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Legendary", PokemonType.Ground, PokemonType.Flying, 1.5f, 68.0f);
		Add(entries, 646, "Kyurem", "Boundary", "This legendary ice Pokémon waits for a hero to fill in the missing parts of its body with truth or ideals. Its body became frozen when its energy leaked out.", "Ilha Gengibre (Recife Oeste) & Profundezas Oceânicas", "Inverno (Qualquer estação nas Minas 40-79)", "Qualquer Clima (Prefere Sol)", "Amanhecer Dourado (06:00h às 10:00h)", "Legendary", PokemonType.Dragon, PokemonType.Ice, 3.0f, 325.0f);
		Add(entries, 647, "Keldeo", "Colt", "When it is resolute, its body fills with power and it becomes swifter. It crosses the world, running over the surfaces of oceans and rivers.", "Ilha Gengibre (Recife Oeste) & Profundezas Oceânicas", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Meia-Noite (22:00h às 02:00h)", "Mythical", PokemonType.Water, PokemonType.Fighting, 1.4f, 48.5f);
		Add(entries, 648, "Meloetta", "Melody", "The melodies sung by Meloetta have the power to make Pokémon that hear them happy or sad. Many famous songs have been inspired by the tunes that Meloetta plays.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera, Verão & Outono", "Qualquer Clima (Sol ou Chuva)", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Mythical", PokemonType.Normal, PokemonType.Psychic, 0.6f, 6.5f);
		Add(entries, 649, "Genesect", "Espécie", "Genesect habita os ecossistemas naturais da região e possui habilidades únicas.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Amanhecer Dourado (06:00h às 10:00h)", "Mythical", PokemonType.Bug, PokemonType.Steel, 1.0f, 20.0f);
		Add(entries, 650, "Chespin", "Spiny Nut", "The quills on its head are usually soft. When it flexes them, the points become so hard and sharp that they can pierce rock without any effort.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, null, 0.4f, 9.0f);
		Add(entries, 651, "Quilladin", "Spiny Armor", "They strengthen the sturdy shell covering their bodies by running into one another. They are very kind and won't start fights, but will counterattack with sharp quills.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, null, 0.7f, 29.0f);
		Add(entries, 652, "Chesnaught", "Spiny Armor", "It shields its allies from danger with its own body. When it takes a defensive posture with its fists guarding its face, it can withstand a bomb blast.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, PokemonType.Fighting, 1.6f, 90.0f);
		Add(entries, 653, "Fennekin", "Fox", "As it walks, it munches on a twig to fill itself with energy in place of a snack. It intimidates opponents by puffing hot air out of its roomy ears.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Fire, null, 0.4f, 9.4f);
		Add(entries, 654, "Braixen", "Fox", "Braixen has a twig stuck in its tail. When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Starter", PokemonType.Fire, null, 1.0f, 14.5f);
		Add(entries, 655, "Delphox", "Fox", "It gazes into the flame at the tip of its branch to achieve a focused state, which allows it to see into the future. It uses psychic power to incinerate its foes.", "Deserto de Calico & Encostas do Vulcão da Ilha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Manhã & Tarde (06:00h às 19:00h)", "Starter", PokemonType.Fire, PokemonType.Psychic, 1.5f, 39.0f);
		Add(entries, 656, "Froakie", "Bubble Frog", "It protects its skin by covering its body in bubbles it secretes from its chest and back. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Water, null, 0.3f, 7.0f);
		Add(entries, 657, "Frogadier", "Bubble Frog", "It can throw bubble-covered pebbles with precise control, hitting empty cans up to a hundred feet away. Frogadier's swiftness is unparalleled.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Starter", PokemonType.Water, null, 0.6f, 10.9f);
		Add(entries, 658, "Greninja", "Ninja", "Greninja habita os ecossistemas naturais da região e possui habilidades únicas.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Primavera & Verão", "Chuva, Tempestade ou Dias Úmidos", "Noturno (18:00h às 02:00h)", "Starter", PokemonType.Water, PokemonType.Dark, 1.5f, 40.0f);
		Add(entries, 659, "Bunnelby", "Digging", "It has ears like shovels. Digging holes strengthens its ears so much that they can sever thick roots effortlessly. Bunnelby dig the whole night through.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Normal, null, 0.4f, 5.0f);
		Add(entries, 660, "Diggersby", "Digging", "With its powerful ears it reduces dense bedrock to rubble. It can be a big help at construction sites. When it's finished digging, it lounges about lazily.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, PokemonType.Ground, 1.0f, 42.4f);
		Add(entries, 661, "Fletchling", "Tiny Robin", "This amiable Pokémon is easy to train. But when battle is joined, it shows its ferocious side. It's merciless to intruders that enter its territory.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Flying, 0.3f, 1.7f);
		Add(entries, 662, "Fletchinder", "Ember", "From its beak, it expels embers that set the tall grass on fire. Then it pounces on any bewildered Pokémon that pop out of the grass.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Fire, PokemonType.Flying, 0.7f, 16.0f);
		Add(entries, 663, "Talonflame", "Scorching", "In the fever of an exciting battle, it showers embers from the gaps between its feathers and takes to the air. It finishes its prey off with a colossal kick.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Fire, PokemonType.Flying, 1.2f, 24.5f);
		Add(entries, 664, "Scatterbug", "Espécie", "Scatterbug habita os ecossistemas naturais da região e possui habilidades únicas.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Bug, null, 1.0f, 20.0f);
		Add(entries, 665, "Spewpa", "Espécie", "Spewpa habita os ecossistemas naturais da região e possui habilidades únicas.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Bug, null, 1.0f, 20.0f);
		Add(entries, 666, "Vivillon", "Espécie", "Its pattern depends on the climate and topography of the land it was born in. This form is from frigid lands. It scatters toxic color scales in battle.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera & Verão", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Bug, PokemonType.Flying, 1.0f, 15.0f);
		Add(entries, 667, "Litleo", "Lion Cub", "They set off on their own from their pride and live by themselves to become stronger. These hot-blooded Pokémon are quick to start a fight.", "Deserto de Calico & Encostas do Vulcão da Ilha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fire, PokemonType.Normal, 0.6f, 13.5f);
		Add(entries, 668, "Pyroar", "Royal", "The male with the largest mane of fire is the leader of the pride. The females protect the pride's cubs. They viciously threaten any challenger.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Fire, PokemonType.Normal, 1.5f, 81.5f);
		Add(entries, 669, "Flabébé", "Espécie", "This Flabébé rides a red flower. Immediately after birth, this Pokémon begins flying around in search of a flower it likes.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Fairy, null, 1.0f, 15.0f);
		Add(entries, 670, "Floette", "Single Bloom", "When evening falls, it searches out a place blooming with flowers of the same white color as itself, and then it goes to sleep.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fairy, null, 0.2f, 0.9f);
		Add(entries, 671, "Florges", "Garden", "The flower it's holding can no longer be found blooming anywhere. It's also thought to contain terrifying power.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Fairy, null, 1.1f, 10.0f);
		Add(entries, 672, "Skiddo", "Mount", "If it has sunshine and water, it doesn't need to eat, because it can generate energy from the leaves on its back. It has a placid disposition.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Sol ou Chuva)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 0.9f, 31.0f);
		Add(entries, 673, "Gogoat", "Mount", "It can tell how its trainer is feeling by subtle shifts in the grip on its horns. This empathetic sense lets them run as if one being. They inhabit mountainous regions.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 1.7f, 91.0f);
		Add(entries, 674, "Pancham", "Playful", "There's no point to the leaf in its mouth, aside from an effort to look cool. It's mischievous, so it's not well suited to inexperienced Trainers.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Fighting, null, 0.6f, 8.0f);
		Add(entries, 675, "Pangoro", "Daunting", "It boasts superb physical strength. Those who wish to become Pangoro's Trainer have no choice but to converse with their fists.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Outono & Inverno", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Fighting, PokemonType.Dark, 2.1f, 136.0f);
		Add(entries, 676, "Furfrou", "Espécie", "Furfrou habita os ecossistemas naturais da região e possui habilidades únicas.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Normal, null, 1.0f, 20.0f);
		Add(entries, 677, "Espurr", "Restraint", "It has enough psychic energy to blast everything within 300 feet of itself. The organ that emits its intense psychic power is sheltered by its ears.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Psychic, null, 0.3f, 3.5f);
		Add(entries, 678, "Meowstic", "Constraint", "The defensive instinct of the males is strong. It's when they're protecting themselves or their partners that they unleash their full power.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Psychic, null, 0.6f, 8.5f);
		Add(entries, 679, "Honedge", "Sword", "If anyone dares to grab its hilt, it wraps a blue cloth around that person's arm and drains that person's life energy completely.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Steel, PokemonType.Ghost, 0.8f, 2.0f);
		Add(entries, 680, "Doublade", "Sword", "When Honedge evolves, it divides into two swords. The complex attack patterns of its two swords are unstoppable, even against those skilled at swordplay.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Steel, PokemonType.Ghost, 0.8f, 4.5f);
		Add(entries, 681, "Aegislash", "Royal Sword", "In this defensive stance, Aegislash uses its steel body and a force field of spectral power to reduce the damage of any attack.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Steel, PokemonType.Ghost, 1.7f, 53.0f);
		Add(entries, 682, "Spritzee", "Perfume", "In the past, rather than using perfume, royal ladies carried a Spritzee that would waft a fragrance they liked. Its fragrance changes depending on what it has eaten.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fairy, null, 0.2f, 0.5f);
		Add(entries, 683, "Aromatisse", "Fragrance", "Its scent is so overpowering that, unless a Trainer happens to really enjoy the smell, he or she will have a hard time walking alongside it.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Fairy, null, 0.8f, 15.5f);
		Add(entries, 684, "Swirlix", "Cotton Candy", "Because it eats nothing but sweets, its fur is as sticky sweet as cotton candy. To entangle its opponents in battle, it extrudes sticky white threads.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono", "Qualquer Clima (Sol ou Chuva)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Fairy, null, 0.4f, 3.5f);
		Add(entries, 685, "Slurpuff", "Meringue", "Slurpuff can distinguish even the faintest of scents. It puts its sensitive sense of smell to use by helping pastry chefs in their work.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fairy, null, 0.8f, 5.0f);
		Add(entries, 686, "Inkay", "Revolving", "It flashes the light-emitting spots on its body, which drains its opponent's will to fight. It takes the opportunity to scuttle away and hide.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Primavera & Verão", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Psychic, 0.4f, 3.5f);
		Add(entries, 687, "Malamar", "Overturning", "It lures prey close with hypnotic motions, then wraps its tentacles around it before finishing it off with digestive fluids. It forces others to do whatever it wants.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Outono & Inverno", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, PokemonType.Psychic, 1.5f, 47.0f);
		Add(entries, 688, "Binacle", "Two-Handed", "They stretch and then contract, yanking their rocks along with them in bold hops. They eat seaweed that washes up on the shoreline.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Rock, PokemonType.Water, 0.5f, 31.0f);
		Add(entries, 689, "Barbaracle", "Collective", "Barbaracle's legs and hands have minds of their own, and they will move independently. But they usually follow the head's orders.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Rock, PokemonType.Water, 1.3f, 96.0f);
		Add(entries, 690, "Skrelp", "Mock Kelp", "Camouflaged as rotten kelp, it hides from foes while storing up power for its evolution. They spray liquid poison on prey that approach unawares.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Poison, PokemonType.Water, 0.5f, 7.3f);
		Add(entries, 691, "Dragalge", "Mock Kelp", "Their poison is strong enough to eat through the hull of a tanker. Tales are told of ships that wander into seas where Dragalge live, never to return.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Poison, PokemonType.Dragon, 1.8f, 81.5f);
		Add(entries, 692, "Clauncher", "Water Gun", "Through controlled expulsions of internal gas, it can expel water like a pistol shot. At close distances, it can even shatter large rocks.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Water, null, 0.5f, 8.3f);
		Add(entries, 693, "Clawitzer", "Howitzer", "By expelling water from the nozzle in the back of its enormous claw, it can move at a speed of 60 knots. They launch cannonballs made of water.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Water, null, 1.3f, 35.3f);
		Add(entries, 694, "Helioptile", "Generator", "They make their home in deserts. They can generate their own energy from basking in the sun, so eating food is not a requirement.", "Montanha, Ferrovia, Torre do Mago & Deserto de Calico", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Electric, PokemonType.Normal, 0.5f, 6.0f);
		Add(entries, 695, "Heliolisk", "Generator", "A single Heliolisk can generate sufficient electricity to power a skyscraper. It can stimulate its muscles with electricity, boosting the strength in its legs.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Electric, PokemonType.Normal, 1.0f, 21.0f);
		Add(entries, 696, "Tyrunt", "Royal Heir", "Its immense jaws have enough destructive force that it can chew up a car. If something happens that it doesn't like, it throws a tantrum and runs wild.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Rock, PokemonType.Dragon, 0.8f, 26.0f);
		Add(entries, 697, "Tyrantrum", "Despot", "Thanks to its gargantuan jaws, which could shred thick metal plates as if they were paper, it was invincible in the ancient world it once inhabited.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Rock, PokemonType.Dragon, 2.5f, 270.0f);
		Add(entries, 698, "Amaura", "Tundra", "This ancient Pokémon was restored from part of its body that had been frozen in ice for over 100 million years. It lived in a cold land where there were no predators.", "Minas Congeladas (Andares 40-79) & Montanha no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Rock, PokemonType.Ice, 1.3f, 25.2f);
		Add(entries, 699, "Aurorus", "Tundra", "Using the diamond-shaped crystals on its body it can instantly create a wall of ice to block an opponent's attack, or encase them in ice.", "Pico da Montanha, Ferrovia & Floresta no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Rock, PokemonType.Ice, 2.7f, 225.0f);
		Add(entries, 700, "Sylveon", "Intertwine", "Its ribbonlike feelers give off an aura that weakens hostility in its prey, causing them to let down their guard. A moment later, it pounces.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fairy, null, 1.0f, 23.5f);
		Add(entries, 701, "Hawlucha", "Wrestling", "With its wings, it controls its position in the air. Its proficient fighting skills enable it to keep up with big bruisers like Machamp and Hariyama.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Fighting, PokemonType.Flying, 0.8f, 21.5f);
		Add(entries, 702, "Dedenne", "Antenna", "Its whiskers serve as antennas. By sending and receiving electrical waves, it can communicate with others over vast distances.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera & Verão", "Tempestade de Raios ou Chuva", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Electric, PokemonType.Fairy, 0.2f, 2.2f);
		Add(entries, 703, "Carbink", "Jewel", "Born from the high temperatures and pressures deep underground, it defends itself by firing beams from the jewel part of its body.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Rock, PokemonType.Fairy, 0.3f, 5.7f);
		Add(entries, 704, "Goomy", "Soft Tissue", "Its source of protection is its slimy, germ-laden mucous membrane. Anyone who touches it will need some thorough hand-washing.", "Caverna da Caveira, Vulcão da Ilha & Cume da Montanha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Dragon, null, 0.3f, 2.8f);
		Add(entries, 705, "Sliggoo", "Soft Tissue", "This Pokémon's mucous can dissolve anything. Toothless, it sprays mucous on its prey. Once they're nicely dissolved, it slurps them up.", "Ilha Gengibre (Cratera do Vulcão) & Caverna dos Piratas", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Dragon, null, 0.8f, 17.5f);
		Add(entries, 706, "Goodra", "Dragon", "It gets picked on because it's meek. But then, whoever teased it gets to feel the full force of its horns and a good swatting from its thick tail.", "Caverna da Caveira, Vulcão da Ilha & Cume da Montanha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Dragon, null, 2.0f, 150.5f);
		Add(entries, 707, "Klefki", "Key Ring", "These key collectors threaten any attackers by fiercely jingling their keys at them. It will sneak into people's homes to steal their keys.", "Caverna da Caveira, Deserto de Calico & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Steel, PokemonType.Fairy, 0.2f, 3.0f);
		Add(entries, 708, "Phantump", "Stump", "According to legend, medicine to cure any illness can be made by plucking the green leaves on its head, brewing them, and boiling down the liquid.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, PokemonType.Grass, 0.4f, 7.0f);
		Add(entries, 709, "Trevenant", "Elder Tree", "Through its roots, it exerts control over other trees. A deadly curse falls upon anyone cutting down trees in forests where Trevenant dwell.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, PokemonType.Grass, 1.5f, 71.0f);
		Add(entries, 710, "Pumpkaboo", "Pumpkin", "The light that streams out from the holes in the pumpkin can hypnotize and control the people and Pokémon that see it.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, PokemonType.Grass, 0.4f, 5.0f);
		Add(entries, 711, "Gourgeist", "Pumpkin", "Eerie cries emanate from its body in the dead of night. The sounds are said to be the wails of spirits who are suffering in the afterlife.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Ghost, PokemonType.Grass, 0.9f, 12.5f);
		Add(entries, 712, "Bergmite", "Ice Chunk", "It blocks opponents' attacks with the ice that shields its body. It uses cold air to repair any cracks with new ice. They live in herds on snowy mountains.", "Minas Congeladas (Andares 40-79) & Montanha no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Ice, null, 1.0f, 99.5f);
		Add(entries, 713, "Avalugg", "Iceberg", "The way several Bergmite huddle on its back make it look like an aircraft carrier made of ice. Its cumbersome frame crushes anything that stands in its way.", "Pico da Montanha, Ferrovia & Floresta no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Ice, null, 2.0f, 505.0f);
		Add(entries, 714, "Noibat", "Sound Wave", "They live in pitch-black caves. Even a robust wrestler will become dizzy and unable to stand when exposed to its 200,000-hertz ultrasonic waves.", "Caverna da Caveira, Vulcão da Ilha & Cume da Montanha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Flying, PokemonType.Dragon, 0.5f, 8.0f);
		Add(entries, 715, "Noivern", "Sound Wave", "They fly around on moonless nights and attack careless prey. The ultrasonic waves it emits from its ears can reduce a large boulder to pebbles.", "Ilha Gengibre (Cratera do Vulcão) & Caverna dos Piratas", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Flying, PokemonType.Dragon, 1.5f, 85.0f);
		Add(entries, 716, "Xerneas", "Life", "Xerneas habita os ecossistemas naturais da região e possui habilidades únicas.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera, Verão & Outono", "Qualquer Clima (Sol ou Chuva)", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Fairy, null, 3.0f, 215.0f);
		Add(entries, 717, "Yveltal", "Destruction", "When its life comes to an end, its wings and tail spread wide and glow red, and it absorbs the life energy of every living thing and turns into a cocoon.", "Caverna da Caveira (Andar 100+) & Templo das Sombras", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Legendary", PokemonType.Dark, PokemonType.Flying, 5.8f, 203.0f);
		Add(entries, 718, "Zygarde", "Order", "Zygarde habita os ecossistemas naturais da região e possui habilidades únicas.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Amanhecer Dourado (06:00h às 10:00h)", "Legendary", PokemonType.Dragon, PokemonType.Ground, 5.0f, 305.0f);
		Add(entries, 719, "Diancie", "Jewel", "A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world. It creates diamonds between its hands.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Meia-Noite (22:00h às 02:00h)", "Mythical", PokemonType.Rock, PokemonType.Fairy, 0.7f, 8.8f);
		Add(entries, 720, "Hoopa", "Mischief", "In its true form, it possess a huge amount of power. When its powers are sealed away, it is transformed into a much smaller form. It teleports things to a secret place.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera, Verão & Outono", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Mythical", PokemonType.Psychic, PokemonType.Ghost, 0.5f, 9.0f);
		Add(entries, 721, "Volcanion", "Steam", "It lets out billows of steam from the arms on its back and disappears into the dense fog. It's said to live in mountains where humans do not tread.", "Vulcão da Ilha Gengibre (Caldeira) & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Amanhecer Dourado (06:00h às 10:00h)", "Mythical", PokemonType.Fire, PokemonType.Water, 1.7f, 195.0f);
		Add(entries, 722, "Rowlet", "Grass Quill", "This wary Pokémon uses photosynthesis to store up energy during the day, while becoming active at night. Silently it glides, drawing near to its target.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, PokemonType.Flying, 0.3f, 1.5f);
		Add(entries, 723, "Dartrix", "Blade Quill", "A bit of a dandy, it spends its free time preening its wings. Its preoccupation with any dirt on its plumage can leave it unable to battle.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Starter", PokemonType.Grass, PokemonType.Flying, 0.7f, 16.0f);
		Add(entries, 724, "Decidueye", "Arrow Quill", "Decidueye is cool and cautious. It fires arrow quills from its wings with such precision, they can pierce a pebble at distances of over a hundred yards.", "Minas Profundas (80-120), Caverna da Caveira & Cemitério", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Starter", PokemonType.Grass, PokemonType.Ghost, 1.6f, 36.6f);
		Add(entries, 725, "Litten", "Fire Cat", "While grooming itself, it builds up fur inside its stomach. It sets the fur alight and spews fiery attacks, which change based on how it coughs.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Fire, null, 0.4f, 4.3f);
		Add(entries, 726, "Torracat", "Fire Cat", "At its throat, it bears a bell of fire. The bell rings brightly whenever this Pokémon spits fire. With a single punch, it can bend an iron bar right over.", "Vulcão da Ilha Gengibre & Minas de Lava (80-120)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Dia Inteiro (06:00h às 02:00h)", "Starter", PokemonType.Fire, null, 0.7f, 25.0f);
		Add(entries, 727, "Incineroar", "Heel", "This Pokémon has a violent, selfish disposition. If it's not in the mood to listen, it will ignore its Trainer's orders with complete nonchalance.", "Deserto de Calico & Encostas do Vulcão da Ilha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Noturno (18:00h às 02:00h)", "Starter", PokemonType.Fire, PokemonType.Dark, 1.8f, 83.0f);
		Add(entries, 728, "Popplio", "Sea Lion", "This Pokémon snorts body fluids from its nose, blowing balloons to smash into its foes. It practices diligently so it can learn to make big bubbles.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Water, null, 0.4f, 7.5f);
		Add(entries, 729, "Brionne", "Pop Star", "It cares deeply for its companions. When its Trainer is feeling down, it performs a cheery dance with a sequence of water balloons to try and help.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Starter", PokemonType.Water, null, 0.6f, 17.5f);
		Add(entries, 730, "Primarina", "Soloist", "It controls its water balloons with song. The melody is learned from others of its kind and is passed down from one generation to the next.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Primavera & Verão", "Chuva, Tempestade ou Dias Úmidos", "Manhã & Tarde (06:00h às 19:00h)", "Starter", PokemonType.Water, PokemonType.Fairy, 1.8f, 44.0f);
		Add(entries, 731, "Pikipek", "Woodpecker", "This Pokémon feeds on berries, whose leftover seeds become the ammunition for the attacks it fires off from its mouth. It uses holes in trees for nesting.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Flying, 0.3f, 1.2f);
