		Add(entries, 733, "Toucannon", "Cannon", "When it battles, within its beak, its internal gases ignite, explosively launching seeds with enough power to pulverize boulders.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Normal, PokemonType.Flying, 1.1f, 26.0f);
		Add(entries, 734, "Yungoos", "Loitering", "With its sharp fangs, it will bite anything. It wanders around in a never-ending search for food. At dusk, it collapses and falls asleep on the spot.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Normal, null, 0.4f, 6.0f);
