		Add(entries, 739, "Crabrawler", "Boxing", "While guarding its weak points with its pincers, it looks for an opening and unleashes punches. When it loses, it foams at the mouth and faints.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Fighting, null, 0.6f, 7.0f);
