		Add(entries, 753, "Fomantis", "Sickle Grass", "During the day, it sleeps and soaks up light. They give off a sweet and refreshing scent. Cutiefly often gather near the tall grass where Fomantis are hiding.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 0.3f, 1.5f);
