		Add(entries, 755, "Morelull", "Illuminate", "As it drowses the day away, it nourishes itself by sucking from tree roots. It wakens at the fall of night, wandering off in search of a new tree.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, PokemonType.Fairy, 0.2f, 1.5f);
