		Add(entries, 775, "Komala", "Drowsing", "It is born asleep, and it dies asleep. All its movements are apparently no more than the results of it tossing and turning in its dreams.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Normal, null, 0.4f, 19.9f);
