		Add(entries, 779, "Bruxish", "Gnash Teeth", "It stuns its prey with its psychic powers and then grinds them to mush with its strong teeth. Even Shellder's shell is no match for it.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Water, PokemonType.Psychic, 0.9f, 19.0f);
		Add(entries, 780, "Drampa", "Placid", "This Pokémon is friendly to people and loves children most of all. It comes from deep in the mountains to play with children it likes in town.", "Caverna da Caveira, Vulcão da Ilha & Cume da Montanha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, PokemonType.Dragon, 3.0f, 185.0f);
