		Add(entries, 784, "Kommo-o", "Scaly", "Kommo-o habita os ecossistemas naturais da região e possui habilidades únicas.", "Caverna da Caveira, Vulcão da Ilha & Cume da Montanha", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Dragon, PokemonType.Fighting, 1.6f, 78.2f);
		Add(entries, 785, "Tapu Koko", "Land Spirit", "It confuses its enemies by flying too quickly for the eye to follow. It has a hair-trigger temper but forgets what made it angry an instant later.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Todas as Estações (Ano Inteiro)", "Tempestade de Raios ou Chuva", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Electric, PokemonType.Fairy, 1.8f, 20.5f);
		Add(entries, 786, "Tapu Lele", "Land Spirit", "A fragrant aroma of flowers follows it. As it flutters about, it scatters its strangely glowing scales. Touching them is said to restore good health.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera & Verão", "Qualquer Clima (Prefere Sol)", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Legendary", PokemonType.Psychic, PokemonType.Fairy, 1.2f, 18.6f);
		Add(entries, 787, "Tapu Bulu", "Land Spirit", "It causes vegetation to grow, and then it absorbs energy from the growth. It pulls large trees up by the roots and swings them around at its enemies.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Chuva Leve ou Céu Limpo", "Amanhecer Dourado (06:00h às 10:00h)", "Legendary", PokemonType.Grass, PokemonType.Fairy, 1.9f, 45.5f);
		Add(entries, 788, "Tapu Fini", "Land Spirit", "People say it can create pure water that will wash away any corruption. The dense fog it creates brings the downfall and destruction of its confused enemies.", "Ilha Gengibre (Recife Oeste) & Profundezas Oceânicas", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Water, PokemonType.Fairy, 1.3f, 21.2f);
		Add(entries, 789, "Cosmog", "Nebula", "In ages past, it was called the child of the stars. It's said to be a Pokémon from another world, but no specific details are known.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Legendary", PokemonType.Psychic, null, 0.2f, 0.1f);
		Add(entries, 790, "Cosmoem", "Protostar", "Motionless as if dead, its body is faintly warm to the touch. There's something accumulating around the black core within its hard shell.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera & Verão", "Qualquer Clima (Prefere Sol)", "Amanhecer Dourado (06:00h às 10:00h)", "Legendary", PokemonType.Psychic, null, 0.1f, 999.9f);
		Add(entries, 791, "Solgaleo", "Sunne", "It is said to live in another world. The intense light it radiates from the surface of its body can make the darkest of nights light up like midday.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Psychic, PokemonType.Steel, 3.4f, 230.0f);
		Add(entries, 792, "Lunala", "Moone", "When its third eye activates, away it flies to another world. This Pokémon devours light, drawing the moonless dark veil of night over the brightness of day.", "Bosque Secreto, Santuário da Ilha & Cume do Vale", "Primavera, Verão & Outono", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Legendary", PokemonType.Psychic, PokemonType.Ghost, 4.0f, 120.0f);
		Add(entries, 793, "Nihilego", "Parasite", "One of several mysterious Ultra Beasts. It's unclear whether or not this Pokémon is sentient, but sometimes it can be observed behaving like a young girl.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Amanhecer Dourado (06:00h às 10:00h)", "Legendary", PokemonType.Rock, PokemonType.Poison, 1.2f, 55.5f);
		Add(entries, 794, "Buzzwole", "Swollen", "This life-form called an Ultra Beast appeared from another world. It shows off its body, but whether that display is a boast or a threat remains unclear.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Meia-Noite (22:00h às 02:00h)", "Legendary", PokemonType.Bug, PokemonType.Fighting, 2.4f, 333.6f);
		Add(entries, 795, "Pheromosa", "Lissome", "One of the dangerous Ultra Beasts, it refuses to touch anything, perhaps because it senses some uncleanness in this world.", "Cume do Vale (The Summit), Caverna da Caveira & Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Crepúsculo & Noite Profunda (18:00h às 02:00h)", "Legendary", PokemonType.Bug, PokemonType.Fighting, 1.8f, 25.0f);
