		Add(entries, 815, "Cinderace", "Striker", "It juggles a pebble with its feet, turning it into a burning soccer ball. Its shots strike opponents hard and leave them scorched.", "Caverna da Caveira & Forja do Vulcão", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Fire, null, 1.4f, 33.0f);
		Add(entries, 816, "Sobble", "Water Lizard", "When scared, this Pokémon cries. Its tears pack the chemical punch of 100 onions, and attackers won't be able to resist weeping.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Dia Inteiro (06:00h às 02:00h)", "Starter", PokemonType.Water, null, 0.3f, 4.0f);
		Add(entries, 817, "Drizzile", "Water Lizard", "A clever combatant, this Pokémon battles using water balloons created with moisture secreted from its palms.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Manhã & Tarde (06:00h às 19:00h)", "Starter", PokemonType.Water, null, 0.7f, 11.5f);
		Add(entries, 818, "Inteleon", "Secret Agent", "It has many hidden capabilities, such as fingertips that can shoot water and a membrane on its back that it can use to glide through the air.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Tarde & Noite (12:00h às 00:00h)", "Starter", PokemonType.Water, null, 1.9f, 45.2f);
		Add(entries, 819, "Skwovet", "Cheeky", "Found throughout the Galar region, this Pokémon becomes uneasy if its cheeks are ever completely empty of berries.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, null, 0.3f, 2.5f);
		Add(entries, 820, "Greedent", "Greedy", "It stashes berries in its tail--so many berries that they fall out constantly. But this Pokémon is a bit slow-witted, so it doesn't notice the loss.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Normal, null, 0.6f, 6.0f);
		Add(entries, 821, "Rookidee", "Tiny Bird", "It will bravely challenge any opponent, no matter how powerful. This Pokémon benefits from every battle--even a defeat increases its strength a bit.", "Deserto de Calico, Fazenda & Arredores da Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Flying, null, 0.2f, 1.8f);
		Add(entries, 822, "Corvisquire", "Raven", "Smart enough to use tools in battle, these Pokémon have been seen picking up rocks and flinging them or using ropes to wrap up enemies.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Primavera & Verão", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Flying, null, 0.8f, 16.0f);
		Add(entries, 823, "Corviknight", "Raven", "This Pokémon reigns supreme in the skies of the Galar region. The black luster of its steel body could drive terror into the heart of any foe.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva Leve ou Céu Limpo", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Flying, PokemonType.Steel, 2.2f, 75.0f);
		Add(entries, 824, "Blipbug", "Larva", "A constant collector of information, this Pokémon is very smart. Very strong is what it isn't.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono", "Qualquer Clima (Sol ou Chuva)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Bug, null, 0.4f, 8.0f);
		Add(entries, 825, "Dottler", "Radome", "It barely moves, but it's still alive. Hiding in its shell without food or water seems to have awakened its psychic powers.", "Floresta Cinzenta, Bosque Secreto & Fazenda", "Todas as Estações (Ano Inteiro)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Bug, PokemonType.Psychic, 0.4f, 19.5f);
		Add(entries, 826, "Orbeetle", "Seven Spot", "It's famous for its high level of intelligence, and the large size of its brain is proof that it also possesses immense psychic power.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Bug, PokemonType.Psychic, 0.4f, 40.8f);
		Add(entries, 827, "Nickit", "Fox", "Aided by the soft pads on its feet, it silently raids the food stores of other Pokémon. It survives off its ill-gotten gains.", "Bosque Secreto Noturno, Esgotos & Pantanal da Bruxa", "Outono & Inverno", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, null, 0.6f, 8.9f);
		Add(entries, 828, "Thievul", "Fox", "It secretly marks potential targets with a scent. By following the scent, it stalks its targets and steals from them when they least expect it.", "Esgotos dos Pelicanos, Covil dos Insetos & Bosque Secreto", "Primavera, Verão & Outono", "Noite Nebulosa, Chuva ou Céu Limpo", "Noturno (18:00h às 02:00h)", "Normal", PokemonType.Dark, null, 1.2f, 19.9f);
		Add(entries, 829, "Gossifleur", "Flowering", "It anchors itself in the ground with its single leg, then basks in the sun. After absorbing enough sunlight, its petals spread as it blooms brilliantly.", "Ilha Gengibre (Selva Tropical) & Bosque Secreto", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 0.4f, 2.2f);
		Add(entries, 830, "Eldegoss", "Cotton Bloom", "The seeds attached to its cotton fluff are full of nutrients. It spreads them on the wind so that plants and other Pokémon can benefit from them.", "Arredores da Vila Pelicanos, Fazenda & Floresta", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Qualquer Clima (Prefere Sol)", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, null, 0.5f, 2.5f);
		Add(entries, 831, "Wooloo", "Sheep", "Its curly fleece is such an effective cushion that this Pokémon could fall off a cliff and stand right back up at the bottom, unharmed.", "Fazenda, Vila Pelicanos & Floresta Cinzenta", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Normal, null, 0.6f, 6.0f);
		Add(entries, 832, "Dubwool", "Sheep", "Weave a carpet from its springy wool, and you end up with something closer to a trampoline. You'll start to bounce the moment you set foot on it.", "Montanha, Ponto de Ônibus & Ilha Gengibre", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Sol ou Chuva)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Normal, null, 1.3f, 43.0f);
		Add(entries, 833, "Chewtle", "Snapping", "Apparently the itch of its teething impels it to snap its jaws at anything in front of it.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Water, null, 0.3f, 8.5f);
		Add(entries, 834, "Drednaw", "Bite", "With jaws that can shear through steel rods, this highly aggressive Pokémon chomps down on its unfortunate prey.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Water, PokemonType.Rock, 1.0f, 115.5f);
		Add(entries, 835, "Yamper", "Puppy", "This Pokémon is very popular as a herding dog in the Galar region. As it runs, it generates electricity from the base of its tail.", "Ilha Gengibre (Ruínas Tropicais), Ferrovia & Vila", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Tempestade de Raios ou Chuva", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Electric, null, 0.3f, 13.5f);
