		Add(entries, 837, "Rolycoly", "Coal", "Most of its body has the same composition as coal. Fittingly, this Pokémon was first discovered in coal mines about 400 years ago.", "Deserto de Calico, Pedreira & Caverna da Caveira", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Rock, null, 0.3f, 12.0f);
