		Add(entries, 841, "Flapple", "Apple Wing", "It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.", "Ilha Gengibre (Cratera do Vulcão) & Caverna dos Piratas", "Primavera, Verão & Outono (Ano todo na Ilha Tropical)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Grass, PokemonType.Dragon, 0.3f, 1.0f);
