		Add(entries, 844, "Sandaconda", "Sand Snake", "When it contracts its body, over 220 pounds of sand sprays from its nose. If it ever runs out of sand, it becomes disheartened.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado / Calor Seco", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Ground, null, 3.8f, 65.5f);
		Add(entries, 845, "Cramorant", "Gulp", "It's so strong that it can knock out some opponents in a single hit, but it also may forget what it's battling midfight.", "Ilha Gengibre (Costa Sul & Rio Tropical) & Praia", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Ensolarado ou Ventania", "Diurno (06:00h às 18:00h)", "Normal", PokemonType.Flying, PokemonType.Water, 0.8f, 18.0f);
		Add(entries, 846, "Arrokuda", "Rush", "If it sees any movement around it, this Pokémon charges for it straightaway, leading with its sharply pointed jaw. It's very proud of that jaw.", "Praia dos Pelicanos, Oceano & Ilha Gengibre (Praia Tropical)", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Chuva, Tempestade ou Dias Úmidos", "Dia Inteiro (06:00h às 02:00h)", "Normal", PokemonType.Water, null, 0.5f, 1.0f);
		Add(entries, 847, "Barraskewda", "Skewer", "This Pokémon has a jaw that's as sharp as a spear and as strong as steel. Apparently Barraskewda's flesh is surprisingly tasty, too.", "Rios da Floresta Cinzenta, Lago da Montanha & Ilha Tropical", "Outono & Inverno", "Chuva Leve ou Céu Limpo", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Water, null, 1.3f, 30.0f);
