		Add(entries, 872, "Snom", "Worm", "It spits out thread imbued with a frigid sort of energy and uses it to tie its body to branches, disguising itself as an icicle while it sleeps.", "Minas Congeladas (Andares 40-79) & Montanha no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Qualquer Clima (Sol ou Chuva)", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Ice, PokemonType.Bug, 0.3f, 3.8f);
