		Add(entries, 874, "Stonjourner", "Big Rock", "It stands in grasslands, watching the sun's descent from zenith to horizon. This Pokémon has a talent for delivering dynamic kicks.", "Minas da Montanha (1-39), Pedreira & Deserto", "Todas as Estações (Primavera, Verão, Outono, Inverno)", "Qualquer Clima (Prefere Sol)", "Manhã & Tarde (06:00h às 19:00h)", "Normal", PokemonType.Rock, null, 2.5f, 520.0f);
		Add(entries, 875, "Eiscue", "Penguin", "It drifted in on the flow of ocean waters from a frigid place. It keeps its head iced constantly to make sure it stays nice and cold.", "Pico da Montanha, Ferrovia & Floresta no Inverno", "Inverno (Qualquer estação nas Minas 40-79)", "Chuva Leve ou Céu Limpo", "Tarde & Noite (12:00h às 00:00h)", "Normal", PokemonType.Ice, null, 1.4f, 89.0f);
