	private static void Add(Dictionary<string, PokedexEntryInfo> entries, int num, string name, string cat, string desc, string habitat, string seasons, string weather, string time, string tier, PokemonType p1, PokemonType? p2, float h, float w)
	{
		entries[name] = new PokedexEntryInfo
		{
			Number = num,
			Name = name,
			Category = cat,
			Description = desc,
			Habitat = habitat,
			Seasons = seasons,
			Weather = weather,
			TimeOfDay = time,
			Tier = tier,
			PrimaryType = p1,
			SecondaryType = p2,
			HeightMeters = h,
			WeightKg = w
		};
	}

	private static readonly Dictionary<string, string> PortugueseDescriptions = new(StringComparer.OrdinalIgnoreCase)
	{
		["Bulbasaur"] = "Bulbasaur costuma ser visto cochilando sob a luz solar intensa. A semente em suas costas cresce progressivamente ao absorver a energia dos raios solares.",
		["Ivysaur"] = "Para sustentar seu bulbo em expansão, suas pernas tornam-se robustas. Ao passar mais tempo descansando ao sol, o broto floresce em uma grande flor.",
		["Venusaur"] = "A flor em suas costas desabrocha com cores deslumbrantes sob farta nutrição e sol. Seu aroma delicado acalma os corações e revigora os ânimos.",
		["Charmander"] = "A chama viva na extremidade de sua cauda reflete seus sentimentos. Ela oscila branda na felicidade e arde furiosamente quando provocado.",
		["Charmeleon"] = "Com garras afiadas e temperamento indomável, despedaça seus adversários. Ao encarar rivais valorosos, a chama em sua cauda reluz em tom azulado.",
		["Charizard"] = "Cruza os céus em busca de grandes batalhas. Suas labaredas abrasadoras derretem rochas e metais, mas honra adversários menores sem atacá-los.",
		["Squirtle"] = "Seu casco hidrodinâmico arredondado minimiza o atrito aquático, atingindo alta velocidade de nado. Dispara jatos d'água precisos pela boca.",
		["Wartortle"] = "Sua cauda elegante e felpuda escurece de tom com o passar das décadas. As ranhuras em seu casco são cicatrizes honrosas de incontáveis vitórias.",
		["Blastoise"] = "Os canhões em sua carapaça blindada disparam poderosos projéteis de água pressurizada capazes de perfurar espessas chapas metálicas a longa distância.",
		["Caterpie"] = "Para afastar predadores, expele um cheiro acre e desagradável de suas antenas bifurcadas. Alimenta-se sem descanso antes de encerrar seu casulo.",
		["Metapod"] = "Sua casca externa é rígida como blindagem de ferro fundido. Mantém-se estático na copa das árvores enquanto remodela sua forma para a metamorfose.",
		["Butterfree"] = "Coleta néctar nas flores mais distantes do vale graças a seu olfato refinado. O pó cintilante em suas asas repele gotas de chuva.",
		["Pikachu"] = "Armazena eletricidade estática em suas bochechas rubras. Quando intimidado, libera faiscantes descargas elétricas para proteger seu bando.",
		["Raichu"] = "Sua cauda comprida serve de condutor terra para descarregar o excesso de eletricidade, evitando sobrecargas de até 100 mil volts.",
		["Gengar"] = "Funde-se à escuridão e se projeta nas sombras transeuntes ao luar. Sente satisfação ao pregar peças e roubar o calor do ambiente ao redor.",
