	public static string GetPortugueseDescription(PokedexEntryInfo entry)
	{
		if (entry == null) return "Sem dados disponíveis na Pokédex.";
		if (!string.IsNullOrEmpty(entry.Name) && PortugueseDescriptions.TryGetValue(entry.Name, out string ptDesc))
		{
			return ptDesc;
		}

		string raw = entry.Description;
		if (string.IsNullOrEmpty(raw))
		{
			string typeStr = entry.SecondaryType.HasValue ? $"{entry.PrimaryType} e {entry.SecondaryType}" : entry.PrimaryType.ToString();
			return $"{entry.Name}, o Pokémon {entry.Category}. Habita comumente {entry.Habitat} durante {entry.Seasons}, demonstrando grande harmonia com {entry.Weather.ToLowerInvariant()}. Canaliza a energia do tipo {typeStr} com grande perícia em combates no Vale.";
		}

		if (raw.Contains("habita") || raw.Contains("possui") || raw.Contains("ecossistemas") || raw.Contains("habilidades"))
		{
			return raw;
		}

		// Synthesize complete, natural Portuguese entry based on official metadata
		string tName = entry.SecondaryType.HasValue ? $"{entry.PrimaryType} e {entry.SecondaryType}" : entry.PrimaryType.ToString();
		return $"{entry.Name}, o Pokémon {entry.Category}. Habita {entry.Habitat} durante {entry.Seasons}. Desenvolveu maestria única para enfrentar os climas de {entry.Weather.ToLowerInvariant()}, empregando o poder de {tName} em combate com notável vitalidade.";
	}

	public static string GetEnglishDescription(PokedexEntryInfo entry)
	{
		if (entry == null) return "No data registered in the Pokédex.";
		if (entry.Name == "Pikachu")
		{
			return "When several of these Pokémon gather, their electricity can build and cause lightning storms. It stores electricity in the electric sacs on its cheeks.";
		}
		if (!string.IsNullOrEmpty(entry.Description) && !entry.Description.Contains("habita") && !entry.Description.Contains("ecossistemas"))
		{
			return entry.Description;
		}
		string typeStr = entry.SecondaryType.HasValue ? $"{entry.PrimaryType}/{entry.SecondaryType}" : entry.PrimaryType.ToString();
		return $"{entry.Name}, the {entry.Category} Pokémon. Commonly found in {entry.Habitat} during {entry.Seasons}. Highly attuned to {entry.Weather.ToLowerInvariant()} weather, it commands the power of {typeStr} in battle.";
	}

	public static string GetLocalizedHabitat(PokedexEntryInfo entry, bool isPt)
	{
		if (entry == null) return "";
		if (isPt) return entry.Habitat;
		string h = entry.Habitat ?? "";
		return h.Replace("Minas Profundas", "Deep Mines")
			.Replace("Caverna da Caveira", "Skull Cavern")
			.Replace("Cemitério", "Graveyard")
			.Replace("Bosque Secreto Noturno", "Night Secret Woods")
			.Replace("Bosque Secreto", "Secret Woods")
			.Replace("Esgotos dos Pelicanos", "Pelican Sewers")
			.Replace("Esgotos", "Sewers")
			.Replace("Covil dos Insetos", "Mutant Bug Lair")
			.Replace("Pantanal da Bruxa", "Witch's Swamp")
			.Replace("Deserto de Calico", "Calico Desert")
			.Replace("Encostas do Vulcão da Ilha", "Island Volcano Slopes")
			.Replace("Vulcão da Ilha Gengibre", "Ginger Island Volcano")
			.Replace("Forja do Vulcão", "Volcano Forge")
			.Replace("Vulcão", "Volcano")
			.Replace("Minas de Lava", "Lava Mines")
			.Replace("Minas da Montanha", "Mountain Mines")
			.Replace("Minas", "Mines")
			.Replace("Rios da Floresta Cinzenta", "Cindersap Forest Rivers")
			.Replace("Lago da Montanha", "Mountain Lake")
			.Replace("Ilha Tropical", "Tropical Island")
			.Replace("Ilha Gengibre", "Ginger Island")
			.Replace("Costa Sul", "South Coast")
			.Replace("Rio Tropical", "Tropical River")
			.Replace("Praia dos Pelicanos", "Pelican Beach")
			.Replace("Praia Tropical", "Tropical Beach")
			.Replace("Praia", "Beach")
			.Replace("Oceano", "Ocean")
			.Replace("Selva Tropical", "Tropical Jungle")
			.Replace("Arredores da Vila Pelicanos", "Pelican Town Outskirts")
			.Replace("Arredores da Vila", "Town Outskirts")
			.Replace("Vila Pelicanos", "Pelican Town")
			.Replace("Vila", "Town")
			.Replace("Fazenda", "Farm")
			.Replace("Floresta Cinzenta", "Cindersap Forest")
			.Replace("Floresta", "Forest")
			.Replace("Montanha", "Mountain")
			.Replace("Ponto de Ônibus", "Bus Stop")
