	public static string GetLocalizedSeasons(PokedexEntryInfo entry, bool isPt)
	{
		if (entry == null) return "";
		if (isPt) return entry.Seasons;
		string s = entry.Seasons ?? "";
		return s.Replace("Todas as Estações", "All Seasons")
			.Replace("Ano todo na Ilha Tropical", "All year on Ginger Island")
			.Replace("Ano Inteiro", "All Year")
			.Replace("Primavera", "Spring")
			.Replace("Verão", "Summer")
			.Replace("Outono", "Fall")
			.Replace("Inverno", "Winter");
	}

	public static string GetLocalizedWeather(PokedexEntryInfo entry, bool isPt)
	{
		if (entry == null) return "";
		if (isPt) return entry.Weather;
		string w = entry.Weather ?? "";
		return w.Replace("Ensolarado / Calor Seco", "Sunny / Dry Heat")
			.Replace("Ensolarado ou Ventania", "Sunny or Windy")
			.Replace("Ensolarado", "Sunny")
			.Replace("Qualquer Clima (Prefere Sol)", "Any Weather (Prefers Sun)")
			.Replace("Qualquer Clima (Sol ou Chuva)", "Any Weather (Sun or Rain)")
			.Replace("Qualquer Clima", "Any Weather")
			.Replace("Chuva Leve ou Céu Limpo", "Light Rain or Clear Sky")
			.Replace("Tempestade de Raios ou Chuva", "Thunderstorm or Rain")
			.Replace("Chuva, Tempestade ou Dias Úmidos", "Rain, Storm, or Humid Days")
			.Replace("Chuva", "Rain")
			.Replace("Tempestade", "Storm")
			.Replace("Ventania", "Windy");
	}

	public static string GetLocalizedTimeOfDay(PokedexEntryInfo entry, bool isPt)
	{
		if (entry == null) return "";
		if (isPt) return entry.TimeOfDay;
		string t = entry.TimeOfDay ?? "";
		return t.Replace("Diurno (06:00h às 18:00h)", "Daytime (6:00 AM - 6:00 PM)")
			.Replace("Noturno (18:00h às 02:00h)", "Nighttime (6:00 PM - 2:00 AM)")
			.Replace("Manhã & Tarde (06:00h às 19:00h)", "Morning & Afternoon (6:00 AM - 7:00 PM)")
			.Replace("Tarde & Noite (12:00h às 00:00h)", "Afternoon & Night (12:00 PM - 12:00 AM)")
			.Replace("Dia Inteiro (06:00h às 02:00h)", "All Day (6:00 AM - 2:00 AM)");
	}
}
